8	import jakarta.persistence.GeneratedValue;
9	import jakarta.persistence.GenerationType;
10	import jakarta.persistence.Id;
11	import jakarta.persistence.JoinColumn;
12	import jakarta.persistence.OneToMany;
13	import jakarta.persistence.OrderBy;
14	import jakarta.persistence.Table;
15	import jakarta.persistence.Transient;
16	import org.hibernate.annotations.Formula;
17	import java.math.BigDecimal;
18	import java.math.BigInteger;
19	import java.math.MathContext;
20	import java.math.RoundingMode;
21	import java.time.LocalDate;
22	import java.time.temporal.ChronoUnit;
23	import java.util.ArrayList;
24	import java.util.Comparator;
25	import java.util.List;
26	import net.officefloor.hq.app.clients.Currency;
27	
28	/** An invoice raised for a client, made of lines. */
29	@Entity
30	@Table(name = "invoice")
31	public class Invoice {
32	
33	    /** A due date set by hand can be at most this many days after the issue date. */
34	    public static final int MAX_DUE_DAYS = 120;
35	
36	    /** Payments that leave less than this many US dollars' worth still due have the rest written off. */
37	    public static final BigDecimal WRITE_OFF_LIMIT = new BigDecimal("1.00");
38	
39	    /** A part payment must be at least this share of the grand total, unless it settles the invoice. */
40	    public static final BigDecimal MINIMUM_PART_SHARE = new BigDecimal("0.10");
41	
42	    /** The most retention a draft can hold back, as a percentage of the amount before tax. */
43	    public static final BigDecimal MAX_RETENTION_PCT = new BigDecimal("20");
44	
45	    /** Released retention falls due this many days after the day it was released. */
46	    public static final int RETENTION_DUE_DAYS = 30;
47	
48	    /** The fewest and most monthly instalments a plan can have. */
49	    public static final int MIN_INSTALMENTS = 2;
50	    public static final int MAX_INSTALMENTS = 24;
51	
52	    /** The highest annual interest rate a plan can charge, as a percentage. */
53	    public static final BigDecimal MAX_INSTALMENT_RATE = new BigDecimal("30");
54	
55	    @Id
56	    @GeneratedValue(strategy = GenerationType.IDENTITY)
57	    private Long id;
58	
59	    @Column(name = "client_id")
60	    private Long clientId;
61	
62	    @Enumerated(EnumType.STRING)
63	    private InvoiceStatus status;
64	
65	    @Column(name = "issue_date")
66	    private LocalDate issueDate;
67	
68	    @Column(name = "due_date")
69	    private LocalDate dueDate;
70	
71	    @Column(name = "manual_due_date")
72	    private boolean manualDueDate;
73	
74	    @Column(name = "discount_pct")
75	    private BigDecimal discountPct = BigDecimal.ZERO;
76	
77	    @Column(name = "discount_amount")
78	    private BigDecimal discountAmount = BigDecimal.ZERO;
79	
80	    @Column(name = "discount_cap")
81	    private BigDecimal discountCap;
82	
83	    @Column(name = "discount_reason")
84	    private String discountReason;
85	
86	    @Column(name = "retention_pct")
87	    private BigDecimal retentionPct = BigDecimal.ZERO;
88	
89	    @Column(name = "retention_released_on")
90	    private LocalDate retentionReleasedOn;
91	
92	    /** The day the late fee and interest still unpaid were last waived; null when never. */
93	    @Column(name = "interest_waived_on")
94	    private LocalDate interestWaivedOn;
95	
96	    /** How many monthly instalments the invoice is spread over; null when it has no plan. */
97	    @Column(name = "instalments")
98	    private Integer instalments;
99	
100	    /** The annual interest rate of the plan, a percentage from 0 to {@link #MAX_INSTALMENT_RATE}. */
101	    @Column(name = "instalment_rate")
102	    private BigDecimal instalmentRate = BigDecimal.ZERO;
103	
104	    /** Whether the invoice's client is tax exempt, so no line is taxed; read from the client. */
105	    @Formula("(SELECT c.tax_exempt FROM client c WHERE c.id = client_id)")
106	    private boolean clientTaxExempt;
107	
108	    /** The id of the invoice this credit note credits; null for an ordinary invoice. */
109	    @Column(name = "credit_of")
110	    private Long creditOf;
111	
112	    /** The code of the currency the invoice's client is billed in; read from the client. */
113	    @Formula("(SELECT c.currency FROM client c WHERE c.id = client_id)")
114	    private String clientCurrency;
115	
116	    /**
117	     * The US dollars one unit of the client's currency is worth, from the workspace rates; read from
118	     * them, null when no rate is set (taken at par).
119	     */
120	    @Formula("(SELECT s.setting_value FROM app_setting s, client c WHERE c.id = client_id AND s.name = 'usd_per_' || c.currency)")
121	    private String usdPer;
122	
123	    /** The client's early-payment discount, a percentage of the grand total; read from the client. */
124	    @Formula("(SELECT c.early_pay_pct FROM client c WHERE c.id = client_id)")
125	    private BigDecimal earlyPayPct;
126	
127	    /** How many days after the issue date the invoice counts as paid off early; read from the client. */
128	    @Formula("(SELECT c.early_pay_days FROM client c WHERE c.id = client_id)")
129	    private Integer earlyPayDays;
130	
131	    /** The early discount the invoice was settled with; 0 when none was taken. */
132	    @Column(name = "early_discount")
133	    private BigDecimal earlyDiscount = BigDecimal.ZERO;
134	
135	    /** An issued credit note's grand total, kept when it is issued; null until then. */
136	    @Column(name = "credit_total")
137	    private BigDecimal creditTotal;
138	
139	    /**
140	     * What this credit note took off its original when issued (what it owed, then retention it held);
141	     * null until then. Any rest of its grand total was held on the client's account as credit.
142	     */
143	    @Column(name = "credit_applied")
144	    private BigDecimal creditApplied;
145	
146	    /** The part of {@link #creditApplied} that cleared retention its original held back. */
147	    @Column(name = "credit_retention")
148	    private BigDecimal creditRetention = BigDecimal.ZERO;
149	
150	    /** What the credit notes issued against this invoice took off it; read from them. */
151	    @Formula("(SELECT COALESCE(SUM(cn.credit_applied), 0) FROM invoice cn WHERE cn.credit_of = id AND cn.status = 'CREDIT_NOTE')")
152	    private BigDecimal credited = BigDecimal.ZERO;
153	
154	    /** The part of what is credited that cleared retention held back; read from the credit notes. */
155	    @Formula("(SELECT COALESCE(SUM(cn.credit_retention), 0) FROM invoice cn WHERE cn.credit_of = id AND cn.status = 'CREDIT_NOTE')")
156	    private BigDecimal retentionCredited = BigDecimal.ZERO;
157	
158	    /** How many credit notes have been issued against this invoice; read from them. */
159	    @Formula("(SELECT COUNT(*) FROM invoice cn WHERE cn.credit_of = id AND cn.status = 'CREDIT_NOTE')")
160	    private int creditNotesIssued;
161	
162	    /**
163	     * The late interest charged so far (see {@link #accrueLateInterest}); not stored, worked out again
164	     * each time the invoice is read.
165	     */
166	    @Transient
167	    private BigDecimal lateInterest = BigDecimal.ZERO;
168	
169	    /**
170	     * The late fee charged (see {@link #accrueLateInterest}), in the invoice's currency; not stored,
171	     * worked out again each time the invoice is read.
172	     */
173	    @Transient
174	    private BigDecimal lateFee = BigDecimal.ZERO;
