484	     * currency is, through the workspace rate, rounded half up to the currency's step.
485	     */
486	    private BigDecimal lateFeeIn(BigDecimal feeUsd) {
487	        if (currency() == Currency.USD) {
488	            return feeUsd.setScale(scale(), RoundingMode.HALF_UP);
489	        }
