494	    /**
495	     * Works out the late fee and late interest charged by the given day, at the late fee (in US
496	     * dollars) and annual rate (a percentage), from the payments (those not reversed count), and keeps
497	     * them as part of what is payable. The fee is charged once, on the day the invoice becomes overdue
498	     * ({@link #GRACE_DAYS} days after its due date), when something is still owed then; it earns no
499	     * interest, and a payment from then on pays it first. A sent invoice not
500	     * spread over instalments, with something still owed more than {@link #GRACE_DAYS} days after its
501	     * due date, earns interest from the end of its grace week ({@link #GRACE_DAYS} days after its due
502	     * date), compounded daily at rate / 365: a balance B owing for
503	     * d days earns B x ((1 + rate / 100 / 365)^d - 1), rounded half up to the cent. Each payment after
504	     * the grace week ends a period; every period earns interest on what the invoice still owed during it
505	     * (earlier interest, the fee and retention left out), and a payment pays the fee, then the interest
506	     * earned so far, then the invoice. An invoice spread over instalments instead earns interest
507	     * instalment by instalment (see {@link #accrueInstalmentInterest}), and no late fee. On the day the
508	     * charges were waived (after the day's payments), the fee and interest still unpaid are written off
509	     * (kept as what was waived) and that day ends a period: interest starts again from it on what is
510	     * still owed, and no new fee is charged.
511	     */
512	    public void accrueLateInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate,
513	            BigDecimal lateFeeUsd, LocalDate today) {
514	        this.lateInterest = BigDecimal.ZERO;
515	        this.lateFee = BigDecimal.ZERO;
516	        this.lateWaived = BigDecimal.ZERO;
517	        this.instalmentInterest = List.of();
518	        if (status == InvoiceStatus.SENT && !isCreditNote() && hasPlan()) {
519	            accrueInstalmentInterest(payments, taxRate, annualRate, today);
520	            return;
521	        }
522	        if (status != InvoiceStatus.SENT || isCreditNote() || hasPlan() || dueDate == null
523	                || !today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
524	            return;
525	        }
526	        boolean earnsInterest = annualRate != null && annualRate.signum() > 0;
527	        BigDecimal fee = lateFeeUsd == null || lateFeeUsd.signum() <= 0 ? zero() : lateFeeIn(lateFeeUsd);
528	        if (!earnsInterest && fee.signum() <= 0) {
529	            return;
530	        }
531	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
532	        }
533	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
534	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
535	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
536	                .filter(p -> !p.on().isAfter(today))
537	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
538	        BigDecimal owed = payableBeforeInterest(taxRate).subtract(retentionReleased(taxRate));
539	        BigDecimal paidInGrace = inOrder.stream().filter(p -> !p.on().isAfter(dueDate.plusDays(GRACE_DAYS)))
540	                .map(Part::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
541	        if (owed.subtract(paidInGrace).signum() <= 0) {
542	            return;
543	        }
544	        BigDecimal daily = earnsInterest
545	                ? BigDecimal.ONE.add(annualRate.divide(BigDecimal.valueOf(36500), MathContext.DECIMAL128))
546	                : null;
547	        LocalDate overdueOn = dueDate.plusDays(GRACE_DAYS + 1);
548	        BigDecimal charged = BigDecimal.ZERO;
549	        BigDecimal unpaidInterest = BigDecimal.ZERO;
550	        BigDecimal unpaidFee = BigDecimal.ZERO;
551	        boolean feeCharged = false;
552	        LocalDate from = dueDate.plusDays(GRACE_DAYS);
553	        LocalDate waiveOn = interestWaivedOn != null && !interestWaivedOn.isBefore(overdueOn)
554	                && !interestWaivedOn.isAfter(today) ? interestWaivedOn : null;
555	        BigDecimal feeWaived = BigDecimal.ZERO;
556	        BigDecimal interestWaived = BigDecimal.ZERO;
557	        for (Part part : inOrder) {
558	            if (waiveOn != null && part.on().isAfter(waiveOn)) {
559	                if (!feeCharged) {
560	                    unpaidFee = fee;
561	                    feeCharged = true;
562	                }
563	                if (earnsInterest && owed.signum() > 0) {
564	                    BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, waiveOn));
565	                    charged = charged.add(earned);
566	                    unpaidInterest = unpaidInterest.add(earned);
567	                }
568	                from = waiveOn;
569	                feeWaived = unpaidFee;
570	                interestWaived = unpaidInterest;
571	                unpaidFee = BigDecimal.ZERO;
572	                unpaidInterest = BigDecimal.ZERO;
573	                waiveOn = null;
574	            }
575	            if (!feeCharged && !part.on().isBefore(overdueOn)) {
576	                unpaidFee = fee;
577	                feeCharged = true;
578	            }
579	            BigDecimal toFee = part.amount().min(unpaidFee).max(BigDecimal.ZERO);
580	            unpaidFee = unpaidFee.subtract(toFee);
581	            BigDecimal rest = part.amount().subtract(toFee);
582	            if (earnsInterest && part.on().isAfter(from) && owed.signum() > 0) {
583	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, part.on()));
584	                charged = charged.add(earned);
585	                unpaidInterest = unpaidInterest.add(earned);
586	                from = part.on();
587	            }
588	            BigDecimal toInterest = rest.min(unpaidInterest).max(BigDecimal.ZERO);
589	            unpaidInterest = unpaidInterest.subtract(toInterest);
590	            owed = owed.subtract(rest.subtract(toInterest));
591	        }
592	        if (waiveOn != null) {
593	            if (earnsInterest && owed.signum() > 0) {
594	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, waiveOn));
595	                charged = charged.add(earned);
596	                unpaidInterest = unpaidInterest.add(earned);
597	            }
598	            from = waiveOn;
599	            feeWaived = feeCharged ? unpaidFee : fee;
600	            interestWaived = unpaidInterest;
601	        }
602	        if (earnsInterest && owed.signum() > 0) {
603	            charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
604	        }
605	        this.lateFee = fee.subtract(feeWaived);
606	        this.lateInterest = charged.subtract(interestWaived);
607	        this.lateWaived = feeWaived.add(interestWaived);
608	    }
609	
610	    /**
611	     * Works out the late interest each instalment of the plan has been charged by the given day, at the
612	     * annual rate (a percentage), from the payments (those not reversed count; what credit notes took
613	     * off counts from the issue date). Payments, in the order they were made, pay each instalment's
614	     * interest earned so far and then the instalment itself, earliest instalment first. An instalment
615	     * still not paid off more than {@link #GRACE_DAYS} days after its due date earns interest by the
616	     * same rule as an invoice: from the end of its own grace week, compounded daily at rate / 365, on
617	     * what is still unpaid of it, with each payment after its grace week ending a period.
618	     */
619	    private void accrueInstalmentInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate,
620	            LocalDate today) {
621	        if (annualRate == null || annualRate.signum() <= 0) {
622	            return;
623	        }
624	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
625	        }
626	        List<Part> inOrder = new ArrayList<>();
627	        if (getCredited().signum() > 0) {
628	            inOrder.add(new Part(issueDate == null ? LocalDate.MIN : issueDate, 0L, getCredited()));
629	        }
630	        payments.stream().filter(p -> !p.isReversed())
631	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
632	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
633	                .filter(p -> !p.on().isAfter(today))
634	                .forEach(inOrder::add);
635	        inOrder.sort(Comparator.comparing(Part::on).thenComparing(Part::paymentId));
636	        BigDecimal[] left = inOrder.stream().map(Part::amount).toArray(BigDecimal[]::new);
637	        BigDecimal daily = BigDecimal.ONE.add(annualRate.divide(BigDecimal.valueOf(36500), MathContext.DECIMAL128));
638	        List<BigDecimal> charges = new ArrayList<>();
639	        BigDecimal total = BigDecimal.ZERO;
640	        for (Instalment instalment : schedule(taxRate)) {
641	            LocalDate due = instalment.dueDate();
642	            BigDecimal owed = instalment.payment();
643	            boolean late = false;
644	            if (due != null && today.isAfter(due.plusDays(GRACE_DAYS))) {
645	                BigDecimal paidInGrace = BigDecimal.ZERO;
646	                for (int j = 0; j < left.length; j++) {
647	                    if (!inOrder.get(j).on().isAfter(due.plusDays(GRACE_DAYS))) {
648	                        paidInGrace = paidInGrace.add(left[j]);
649	                    }
650	                }
651	                late = paidInGrace.compareTo(owed) < 0;
652	            }
653	            BigDecimal charged = BigDecimal.ZERO;
654	            BigDecimal unpaidInterest = BigDecimal.ZERO;
655	            LocalDate from = due == null ? null : due.plusDays(GRACE_DAYS);
656	            for (int j = 0; j < left.length; j++) {
657	                Part part = inOrder.get(j);
658	                if (late && part.on().isAfter(from) && owed.signum() > 0) {
659	                    BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, part.on()));
660	                    charged = charged.add(earned);
661	                    unpaidInterest = unpaidInterest.add(earned);
662	                    from = part.on();
663	                }
664	                BigDecimal toInterest = left[j].min(unpaidInterest).max(BigDecimal.ZERO);
665	                unpaidInterest = unpaidInterest.subtract(toInterest);
666	                BigDecimal toOwed = left[j].subtract(toInterest).min(owed).max(BigDecimal.ZERO);
667	                owed = owed.subtract(toOwed);
668	                left[j] = left[j].subtract(toInterest).subtract(toOwed);
669	            }
670	            if (late && owed.signum() > 0) {
671	                charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
672	            }
673	            charges.add(charged.setScale(scale(), RoundingMode.HALF_UP));
674	            total = total.add(charged);
675	        }
676	        this.instalmentInterest = charges;
677	        this.lateInterest = total;
678	    }
679	
680	    /** The interest the balance earns over the days at the daily growth factor, rounded half up to the cent. */
681	    private BigDecimal interestOn(BigDecimal balance, BigDecimal daily, long days) {
682	        if (days <= 0) {
683	            return zero();
684	        }
685	        return balance.multiply(daily.pow((int) days, MathContext.DECIMAL128).subtract(BigDecimal.ONE))
686	                .setScale(scale(), RoundingMode.HALF_UP);
687	    }
688	
689	    /**
690	     * The early-payment discount on offer at the tax rate: the client's early-payment percentage of the
691	     * grand total, rounded down to the cent; nothing for a credit note, or an invoice holding back
692	     * retention or spread over instalments.
693	     */
694	    public BigDecimal earlyDiscount(BigDecimal taxRate) {
695	        if (isCreditNote() || hasPlan() || retentionPct.signum() > 0 || earlyPayDays == null
