754	    /**
755	     * The plan's schedule at the tax rate, an ordinary loan of the grand total; empty when there is no
756	     * plan. With the monthly rate i (the annual rate / 12 / 100) the instalment is P x i / (1 - (1 +
757	     * i)^-n), or P / n at 0%, rounded half up to the cent. Each month's interest is the balance still
758	     * owed x i, rounded half up to the cent, and its principal the instalment less the interest; the
759	     * last instalment pays off the whole balance left plus its interest, so the schedule ends at zero.
760	     * Instalment k falls due k months after the issue date, on the same day (the month's last day when
761	     * it is shorter).
762	     */
763	    public List<Instalment> schedule(BigDecimal taxRate) {
764	        if (!hasPlan()) {
765	            return List.of();
766	        }
767	        MathContext mc = MathContext.DECIMAL128;
768	        BigDecimal principal = total(taxRate);
769	        BigDecimal i = instalmentRate.divide(BigDecimal.valueOf(1200), mc);
770	        int n = instalments;
771	        BigDecimal payment;
772	        if (i.signum() == 0) {
773	            payment = principal.divide(BigDecimal.valueOf(n), scale(), RoundingMode.HALF_UP);
774	        } else {
775	            BigDecimal growth = BigDecimal.ONE.add(i).pow(n, mc);
776	            payment = principal.multiply(i).multiply(growth)
777	                    .divide(growth.subtract(BigDecimal.ONE), mc).setScale(scale(), RoundingMode.HALF_UP);
778	        }
779	        List<Instalment> schedule = new ArrayList<>(n);
780	        BigDecimal balance = principal.setScale(scale(), RoundingMode.HALF_UP);
781	        for (int k = 1; k <= n; k++) {
782	            BigDecimal interest = balance.multiply(i).setScale(scale(), RoundingMode.HALF_UP);
783	            BigDecimal paid = k == n ? balance.add(interest) : payment;
784	            BigDecimal repaid = paid.subtract(interest);
785	            balance = balance.subtract(repaid);
786	            LocalDate due = issueDate == null ? null : issueDate.plusMonths(k);
787	            schedule.add(new Instalment(k, due, paid, interest, repaid, balance));
788	        }
789	        return schedule;
790	    }
