800	    /**
801	     * Each instalment of the plan at the tax rate once the given amount has been paid, on the given
802	     * day: payments (with what credit notes took off and anything written off) pay the instalments in
803	     * order, each its late interest and then itself, each paid off before the next. An instalment not
804	     * paid off more than {@link #GRACE_DAYS} days after its due date is overdue; empty when there is no
805	     * plan.
806	     */
807	    public List<Instalment.Progress> instalmentProgress(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
808	        List<Instalment.Progress> progress = new ArrayList<>();
809	        BigDecimal left = paid.add(getCredited()).add(writtenOff(paid, taxRate));
810	        List<Instalment> schedule = schedule(taxRate);
811	        for (int k = 0; k < schedule.size(); k++) {
812	            Instalment instalment = schedule.get(k);
813	            BigDecimal interest = k < instalmentInterest.size() ? instalmentInterest.get(k) : zero();
814	            BigDecimal toInterest = left.min(interest).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
815	            left = left.subtract(toInterest);
816	            BigDecimal interestUnpaid = interest.subtract(toInterest);
817	            BigDecimal part = left.min(instalment.payment()).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
818	            left = left.subtract(part);
819	            BigDecimal unpaid = instalment.payment().subtract(part);
820	            Instalment.Status status;
821	            if (unpaid.signum() <= 0 && interestUnpaid.signum() <= 0) {
822	                status = Instalment.Status.PAID;
823	            } else if (instalment.dueDate() != null && today.isAfter(instalment.dueDate().plusDays(GRACE_DAYS))) {
824	                status = Instalment.Status.OVERDUE;
825	            } else if (part.signum() > 0) {
826	                status = Instalment.Status.PART_PAID;
827	            } else {
828	                status = Instalment.Status.DUE;
829	            }
830	            progress.add(new Instalment.Progress(instalment, part, unpaid, interest, interestUnpaid, status));
831	        }
832	        return progress;
833	    }
