836	     * What is overdue at the tax rate once the given amount has been paid, on the given day: for a plan,
837	     * only what is unpaid on its overdue instalments, their late interest included; otherwise all that is due when it is overdue.
838	     */
839	    public BigDecimal overdueAmount(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
840	        if (statusWhenPaid(paid, taxRate, today) != InvoiceStatus.OVERDUE) {
