952	    /**
953	     * As {@link #statusWhenPaid(BigDecimal, BigDecimal, LocalDate)}, but a fully paid invoice whose
954	     * paid date (null when not known) is after its due date is paid late.
955	     */
956	    public InvoiceStatus statusWhenPaid(BigDecimal paid, LocalDate paidOn, BigDecimal taxRate, LocalDate today) {
957	        if (status != InvoiceStatus.SENT) {
958	            return status;
959	        }
960	        BigDecimal amountDue = amountDue(paid, taxRate);
961	        boolean due = amountDue.signum() > 0;
962	        BigDecimal retentionDue = amountDue.min(retentionReleased(taxRate)).max(BigDecimal.ZERO);
963	        boolean restDue = amountDue.subtract(retentionDue).signum() > 0;
964	        if (hasPlan()) {
965	            if (due && instalmentProgress(paid, taxRate, today).stream()
966	                    .anyMatch(p -> p.status() == Instalment.Status.OVERDUE)) {
967	                return InvoiceStatus.OVERDUE;
968	            }
969	        } else if (restDue && dueDate != null && today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
970	            return InvoiceStatus.OVERDUE;
971	        }
972	        if (retentionDue.signum() > 0 && today.isAfter(retentionDueDate().plusDays(GRACE_DAYS))) {
973	            return InvoiceStatus.OVERDUE;
974	        }
975	        if (!due && retentionHeld(taxRate).signum() > 0) {
976	            return InvoiceStatus.RETENTION_HELD;
977	        }
978	        if (paid.signum() <= 0) {
979	            return !due && getCredited().signum() > 0 ? InvoiceStatus.CREDITED : status;
980	        }
981	        if (due) {
982	            return InvoiceStatus.PART_PAID;
983	        }
984	        return paidOn != null && dueDate != null && paidOn.isAfter(dueDate) ? InvoiceStatus.PAID_LATE
985	                : InvoiceStatus.PAID;
986	    }
