988	    /**
989	     * The date the invoice was fully paid: the date of the payment that cleared its grand total at the
990	     * tax rate, taking the parts of payments (not reversed) in the order they were applied (credit used
991	     * counts on the day it was applied); null while something is still due or retention is held.
992	     */
993	    public LocalDate paidOn(List<Payment> payments, BigDecimal taxRate) {
994	        BigDecimal total = payable(taxRate);
995	        if (status != InvoiceStatus.SENT || total.signum() <= 0 || retentionHeld(taxRate).signum() > 0) {
996	            return null;
997	        }
998	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
999	        }
1000	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
1001	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
1002	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
1003	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
1004	        BigDecimal sum = BigDecimal.ZERO;
1005	        for (Part p : inOrder) {
1006	            sum = sum.add(p.amount());
1007	            if (sum.signum() > 0 && isSmallEnoughToWriteOff(total.subtract(sum))) {
1008	                return p.on();
1009	            }
1010	        }
1011	        return null;
1012	    }
