1014	    /**
1015	     * What is still due once the given amount has been paid: the grand total less it, less what credit
1016	     * notes have credited, less the retention still held, less anything written off — so nothing once
1017	     * payments leave less than {@link #WRITE_OFF_LIMIT}. A credit note itself has nothing due.
1018	     */
1019	    public BigDecimal amountDue(BigDecimal paid, BigDecimal taxRate) {
1020	        if (isCreditNote()) {
1021	            return zero();
1022	        }
1023	        return payable(taxRate).subtract(paid).subtract(writtenOff(paid, taxRate));
1024	    }
