1026	    /**
1027	     * What is written off once the given amount has been paid: when payments leave less than
1028	     * {@link #WRITE_OFF_LIMIT} still due, all of what is left; otherwise nothing.
1029	     */
1030	    public BigDecimal writtenOff(BigDecimal paid, BigDecimal taxRate) {
1031	        BigDecimal left = payable(taxRate).subtract(paid);
1032	        return !isCreditNote() && paid.signum() > 0 && left.signum() > 0 && isSmallEnoughToWriteOff(left)
1033	                ? left.setScale(scale(), RoundingMode.HALF_UP)
1034	                : zero();
1035	    }
