1042	    /**
1043	     * Whether paying the amount on top of what was already paid is too small a part payment: under
1044	     * {@link #minimumPart} while leaving something still due (what would be written off counts as settled).
1045	     * For a plan the least is instead what is still unpaid on its earliest unpaid instalment.
1046	     */
1047	    public boolean isTooSmallPart(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
1048	        if (hasPlan()) {
1049	            return amount.compareTo(earliestUnpaid(paid, taxRate)) < 0
1050	                    && amountDue(paid.add(amount), taxRate).signum() > 0;
1051	        }
1052	        return amount.compareTo(minimumPart(taxRate)) < 0 && amountDue(paid.add(amount), taxRate).signum() > 0;
1053	    }
