1105	    /**
1106	     * The sum of the line amounts, each after its own discount and already to the cent — so the subtotal
1107	     * matches what a client gets by adding up the lines shown.
1108	     */
1109	    public BigDecimal subtotal() {
1110	        return lines.stream().map(l -> l.amount(scale()))
1111	                .reduce(zero(), BigDecimal::add);
1112	    }
1113	
1114	    /**
1115	     * The amount taken off: the fixed amount when there is one (never more than the subtotal, should
1116	     * lines have been changed since), otherwise the discount percentage of the subtotal, rounded down
1117	     * to the cent. When there is a cap, it limits everything taken off — the line discounts plus
1118	     * this — so this shrinks to what the line discounts leave under the cap, never below zero.
1119	     */
1120	    public BigDecimal discount() {
1121	        BigDecimal discount = discountAmount.signum() > 0
1122	                ? discountAmount.min(subtotal()).setScale(scale(), RoundingMode.HALF_UP)
1123	                : subtotal().multiply(discountPct).divide(BigDecimal.valueOf(100)).setScale(scale(), RoundingMode.DOWN);
1124	        if (discountCap == null) {
1125	            return discount;
1126	        }
1127	        BigDecimal lineDiscounts = lines.stream().map(l -> l.discount(scale()))
1128	                .reduce(zero(), BigDecimal::add);
1129	        BigDecimal left = discountCap.setScale(scale(), RoundingMode.HALF_UP).subtract(lineDiscounts).max(zero());
1130	        return discount.min(left);
1131	    }
