1133	    /**
1134	     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
1135	     * proportion to the line amounts: each line first gets the whole cents of its exact share
1136	     * (rounded down), then the cents left over go one each to the lines with the largest leftover
1137	     * fractions; between equal fractions the cent goes to the line with the larger amount, and between
1138	     * equal amounts too to the lower line id. The shares add up to the discount.
1139	     */
1140	    public List<BigDecimal> discountShares() {
1141	        BigInteger discountCents = discount().movePointRight(scale()).toBigIntegerExact();
1142	        BigInteger subtotalCents = subtotal().movePointRight(scale()).toBigIntegerExact();
1143	        int n = lines.size();
1144	        BigInteger[] shares = new BigInteger[n];
1145	        BigInteger[] leftovers = new BigInteger[n];
1146	        BigInteger given = BigInteger.ZERO;
1147	        for (int i = 0; i < n; i++) {
1148	            if (subtotalCents.signum() == 0) {
1149	                shares[i] = BigInteger.ZERO;
1150	                leftovers[i] = BigInteger.ZERO;
1151	            } else {
1152	                // The exact share is discount * amount / subtotal; all fractions share the subtotal
1153	                // as denominator, so the remainders compare as the fractions do.
1154	                BigInteger[] qr = discountCents.multiply(lines.get(i).amount(scale()).movePointRight(scale()).toBigIntegerExact())
1155	                        .divideAndRemainder(subtotalCents);
1156	                shares[i] = qr[0];
1157	                leftovers[i] = qr[1];
1158	            }
1159	            given = given.add(shares[i]);
1160	        }
1161	        List<Integer> order = new ArrayList<>();
1162	        for (int i = 0; i < n; i++) {
1163	            order.add(i);
1164	        }
1165	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
1166	                .thenComparing(Comparator.<Integer, BigDecimal>comparing(i -> lines.get(i).amount(scale())).reversed())
1167	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
1168	        int left = discountCents.subtract(given).intValueExact();
1169	        for (int k = 0; k < left; k++) {
1170	            int i = order.get(k);
1171	            shares[i] = shares[i].add(BigInteger.ONE);
1172	        }
1173	        List<BigDecimal> result = new ArrayList<>(n);
1174	        for (BigInteger share : shares) {
1175	            result.add(new BigDecimal(share, scale()));
1176	        }
1177	        return result;
1178	    }
