1180	    /**
1181	     * Each line's tax, in the order of the lines: the line's own rate (a percentage), or the given
1182	     * workspace rate when it has none, on the line's amount less its share of the discount, rounded
1183	     * half up to the cent. Tax-exempt lines, and every line of a tax-exempt client, have no tax.
1184	     */
1185	    public List<BigDecimal> lineTaxes(BigDecimal taxRate) {
1186	        List<BigDecimal> shares = discountShares();
1187	        List<BigDecimal> taxes = new ArrayList<>(lines.size());
1188	        for (int i = 0; i < lines.size(); i++) {
1189	            InvoiceLine line = lines.get(i);
1190	            taxes.add(clientTaxExempt || line.isTaxExempt() ? zero()
1191	                    : line.amount(scale()).subtract(shares.get(i)).multiply(line.taxRate(taxRate)).divide(BigDecimal.valueOf(100))
1192	                            .setScale(scale(), RoundingMode.HALF_UP));
1193	        }
1194	        return taxes;
1195	    }
1196	
1197	    /** The tax charged at the given rate (a percentage): the sum of the line taxes. */
1198	    public BigDecimal tax(BigDecimal taxRate) {
1199	        return lineTaxes(taxRate).stream().reduce(zero(), BigDecimal::add);
1200	    }
1201	
1202	    /** The grand total: the subtotal less the discount, plus tax at the given rate. */
1203	    public BigDecimal total(BigDecimal taxRate) {
1204	        return subtotal().subtract(discount()).add(tax(taxRate));
1205	    }
